import os
from contextlib import contextmanager

@contextmanager
def temp_environ(key, value):
    original_value = os.environ.get(key)
    os.environ[key] = value
    try:
        yield
    finally:
        if original_value is None:
            ___  # 恢复为未设置状态
        else:
            os.environ[key] = original_value

class MyContext:
    def __enter__(self):
        print('enter')
        return self
    def __exit__(self, *args):
        print('exit')
        return True

try:
    with MyContext() as c:
